import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        w = int(next(iterator))

        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        b = []
        for _ in range(w):
            b.append(int(next(iterator)))

    except StopIteration:
        return

    if w > n:
        print(0)
        return

    if w == 1:
        print(n)
        return

    # Compute differences for array a
    diff_a = [a[i+1] - a[i] for i in range(n-1)]

    # Compute differences for array b
    diff_b = [b[i+1] - b[i] for i in range(w-1)]

    # We need to find occurrences of diff_b in diff_a
    # Using KMP algorithm

    # Build prefix function (pi table) for diff_b
    m = len(diff_b)
    pi = [0] * m
    k = 0
    for q in range(1, m):
        while k > 0 and diff_b[k] != diff_b[q]:
            k = pi[k-1]
        if diff_b[k] == diff_b[q]:
            k += 1
        pi[q] = k

    # Search diff_b in diff_a
    count = 0
    q = 0  # number of characters matched
    for i in range(len(diff_a)):
        while q > 0 and diff_b[q] != diff_a[i]:
            q = pi[q-1]
        if diff_b[q] == diff_a[i]:
            q += 1
        if q == m:
            count += 1
            q = pi[q-1]

    print(count)

if __name__ == '__main__':
    solve()
